#ifndef F_FONTS_H
#define F_FONTS_H

#include <stdint.h>
#include "lvgl.h"

// Bitmap font families generated by tools/gen_text_widget_fonts.sh.
typedef enum
{
  FONT_FAMILY_SANS = 0, // Montserrat Medium
  FONT_FAMILY_BOLD = 1, // DejaVu Sans Bold
  FONT_FAMILY_COUNT
} font_family_t;

#define FONT_SIZE_MIN 8
#define FONT_SIZE_MAX 36

// Largest generated size <= size_px (clamped to FONT_SIZE_MIN..FONT_SIZE_MAX). Never NULL.
const lv_font_t *font_registry_get(uint8_t family, uint8_t size_px);

// Sans font whose capital letters are closest to cap_px tall. Reaches beyond FONT_SIZE_MAX so
// text next to digit sprites can match their height. Never NULL.
const lv_font_t *font_registry_match_cap(uint8_t cap_px);

#endif
